<?php/** * Created by PhpStorm. * User: zy * Date: 2020/3/4 * Time: 15:31 */namespace App\Http\Controllers\V1\CategoryTemplate;use App\Exceptions\Error;use App\Http\Controllers\V1\BaseController;use CrsSdk\Shop\CategoryTemplate;use Exception;use Illuminate\Http\Request;use Illuminate\Support\Facades\Log;use Illuminate\Validation\ValidationException;class UpdateCategoryGoodsSortController extends BaseController{    /**     * @param Request $request     * @return array     * @throws ValidationException     */    public function index(Request $request)    {        $input                  = $this->getParams($request);        $input['enterprise_id'] = $this->enterpriseId;        $result = [];        try {            $result = (new CategoryTemplate())->UpdateCategoryGoodsSort($input);        } catch (Error $error) {            Log::info('修改分类关联商品权重失败', $error->data);            notice(100000, [$error->getMessage()]);        } catch (Exception $e) {            Log::info('修改分类关联商品权重失败' . $e->getMessage(), $input);            notice(100000, [$e->getMessage()]);        }        return success($result);    }    /**     * 验证数据     * @param $request     * @return array     * @throws ValidationException     */    protected function getParams($request)    {        // 验证参数        $rule = [            'id'       => 'required|integer',            'cate_id'  => 'required|integer',            'sort_num' => 'required|integer|min:0|max:9999',        ];        $messages = [            'id.*'       => '关联ID不存在',            'cate_id.*'  => '分类不存在',            'sort_num.*' => '权重值有误,设置范围:(0-9999)',        ];        return $this->validate($request, $rule, $messages);    }}